<template><view class="page"><view class="top"><text class="title">共享广场</text><text class="sub">看看大家正在记录什么</text></view><view class="banner"><text>好想法，值得被看见</text><text>把你的笔记分享给更多人　→</text></view><view class="filters"><text>推荐</text><text>最新</text><text>热门</text></view><view class="card" v-for="n in notes.filter(x=>x.shared)" :key="n._id" @click="detail(n._id)"><view class="author"><view class="avatar">{{n.author.slice(0,1)}}</view><view><text class="author-name">{{n.author}}</text><text class="category">{{n.category}} · {{n.updatedAt}}</text></view><text class="follow">＋ 关注</text></view><text class="name">{{n.title}}</text><text class="desc">{{n.summary}}</text><view class="chips">#{{n.tags.join('　#')}}</view><view class="actions"><text>♡　{{n._id==='n1'?'128':'86'}}</text><text>◯　分享</text><text>＋　收藏</text></view></view></view></template>
<script setup>import {notes} from '../../src/data/demo.js';function detail(id){uni.navigateTo({url:'/pages/detail/detail?id='+id})}</script>
<style scoped>.page{padding:24px 20px}.top{margin:8px 0 19px}.title{display:block;font-size:25px;font-weight:700}.sub{display:block;margin-top:8px;font-size:12px;color:#9298a1}.banner{padding:19px;border-radius:16px;background:linear-gradient(120deg,#586ff0,#8d9cff);color:white}.banner text{display:block}.banner text:first-child{font-size:17px;font-weight:700}.banner text+text{margin-top:9px;font-size:11px;color:#e5e8ff}.filters{display:flex;gap:22px;padding:20px 4px 8px;color:#979ca5;font-size:13px}.filters text:first-child{color:#536cf1;font-weight:700}.card{padding:16px;margin-top:10px;background:#fff;border-radius:16px}.author{display:flex;align-items:center}.avatar{width:35px;height:35px;border-radius:13px;background:#e9edff;color:#536cf1;text-align:center;line-height:35px}.author-name,.category{display:block;margin-left:10px}.author-name{font-size:12px;font-weight:600}.category{margin-top:4px;font-size:10px;color:#9ba0a8}.follow{margin-left:auto;border:1px solid #dfe3ff;color:#536cf1;border-radius:12px;padding:5px 10px;font-size:10px}.name{display:block;margin-top:17px;font-size:16px;font-weight:700}.desc{display:block;margin-top:8px;font-size:12px;line-height:1.7;color:#717883}.chips{margin-top:10px;color:#536cf1;font-size:11px}.actions{display:flex;justify-content:space-between;margin-top:16px;padding-top:13px;border-top:1px solid #f1f2f4;color:#9298a1;font-size:11px}</style>
